# Regenerates icons.json / icons.css from the Lucide SVGs (npm pack lucide-static; tar xf; LUCIDE=package/icons)
import re,urllib.parse,json,pathlib,os
SRC=pathlib.Path(os.environ.get('LUCIDE','package/icons'))
NAMES="""search undo-2 upload folder-plus file-plus headphones sliders-horizontal x folder folder-open file file-text file-audio image film file-archive file-code chevron-right chevron-down share pencil trash-2 scissors copy clipboard-paste download list-checks arrow-left arrow-up arrow-right layout-grid list play pause skip-back skip-forward volume-2 crosshair panel-left-close panel-left plus minus wrap-text pin eye files log-in log-out user lock key-round house link radio message-square-text check circle-alert rotate-cw maximize info hard-drive folder-up refresh-cw repeat shuffle music cloud-upload square-check-big text-cursor-input settings-2 gauge zap dices shield calendar ruler tag history circle-x circle-check loader file-search sun moon cloud ellipsis chevron-left chevrons-up-down volume-x square folder-tree keyboard qr-code monitor hash type save columns-2 eye-off folder-down circle-dot arrow-down-up chevron-up clock moon-star sunset wand-sparkles grip-vertical""".split()
out={}
for n in NAMES:
    s=(SRC/f'{n}.svg').read_text()
    s=re.sub(r'<!--.*?-->','',s,flags=re.S);inner=re.search(r'<svg[^>]*>(.*)</svg>',s,re.S).group(1).strip()
    inner=re.sub(r'\s+',' ',inner)
    out[n]=inner
pathlib.Path('icons.json').write_text(json.dumps(out))
def svg(n,sw=1.5):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="{sw}" stroke-linecap="round" stroke-linejoin="round">{out[n]}</svg>'
css=['/* Icons: Lucide v1.72.0 (ISC License, (c) Lucide Contributors), stroke 1.5. Generated by src/vendor/icons.py */',':root{']
for n in NAMES:
    css.append(f'--ni-{n}:url("data:image/svg+xml,{urllib.parse.quote(svg(n))}");')
css.append('}')
css.append('.ni{display:inline-block;width:1.15em;height:1.15em;flex:none;vertical-align:-.2em;background:currentColor;-webkit-mask:var(--ni) center/contain no-repeat;mask:var(--ni) center/contain no-repeat}')
for n in NAMES: css.append(f'.ni-{n}{{--ni:var(--ni-{n})}}')
pathlib.Path('icons.css').write_text('\n'.join(css))
print(len(NAMES),'icons')
